import{_ as n,C as i,o,c as t,E as s,a2 as r}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"Weekly 001 — From Agent Frameworks to Governed Digital Employees","description":"","frontmatter":{"title":"Weekly 001 — From Agent Frameworks to Governed Digital Employees","date":"2026-07-31","column":"digital-employee","category":"weekly","summary":"The first synthesis of interoperability, open-source runtime engineering, enterprise digital workforce products and CodeFlowMu positioning.","outline":"deep","cover":"/assets/covers/weekly-001-cover-v2.jpg"},"headers":[],"relativePath":"en/research/weekly/weekly-001.md","filePath":"en/research/weekly/weekly-001.md","lastUpdated":1787407830000}'),l={name:"en/research/weekly/weekly-001.md"};function c(p,e,d,u,m,h){const a=i("ArticleCover");return o(),t("div",null,[s(a,{image:"/assets/covers/weekly-001-cover-v2.jpg",kicker:"Weekly Research · 001",title:"From Agent Frameworks to Governed Digital Employees",summary:"The first synthesis of interoperability, open-source runtime engineering, enterprise digital workforce products and CodeFlowMu positioning.",version:"W001",status:"Published 2026-07-31",languageHref:"/zh/research/weekly/weekly-001",languageLabel:"简体中文"}),e[0]||(e[0]=r(`<h2 id="executive-synthesis" tabindex="-1">Executive synthesis <a class="header-anchor" href="#executive-synthesis" aria-label="Permalink to &quot;Executive synthesis&quot;">​</a></h2><p>The first weekly report established the Research Center baseline:</p><ol><li>interoperability is becoming infrastructure while governance remains the missing layer;</li><li>open-source systems are moving from chat Agents toward runtime, orchestration and operator control;</li><li>enterprise vendors are packaging Digital Workforce products rather than generic Agent capability;</li><li>CodeFlowMu should not become another general-purpose multi-agent framework;</li><li>the stable product direction is an SME-first Digital Employee development and runtime platform.</li></ol><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Digital Employee</span></span>
<span class="line"><span>= Position</span></span>
<span class="line"><span>+ Responsibility</span></span>
<span class="line"><span>+ Skills</span></span>
<span class="line"><span>+ Workflow</span></span>
<span class="line"><span>+ Runtime</span></span>
<span class="line"><span>+ Governance</span></span>
<span class="line"><span>+ Evaluation</span></span></code></pre></div><h2 id="academic-signal" tabindex="-1">Academic signal <a class="header-anchor" href="#academic-signal" aria-label="Permalink to &quot;Academic signal&quot;">​</a></h2><p>Protocol research around MCP, A2A, ACP and related standards shows that tool access and interoperability do not automatically provide membership, responsibility, dissent, human escalation, audit or replay. TMPA should therefore sit above or alongside interoperability protocols as a work-data and governance architecture rather than compete as another universal communication protocol.</p><h2 id="open-source-engineering-signal" tabindex="-1">Open-source engineering signal <a class="header-anchor" href="#open-source-engineering-signal" aria-label="Permalink to &quot;Open-source engineering signal&quot;">​</a></h2><p>OpenHands, AutoGen and related systems are increasingly adding resumable execution, nested teams, skills, plugins, MCP integration, connection health and operator controls. These are becoming baseline runtime primitives. They still do not define a persistent organizational Position, accountable owner, completion evidence or publication authority.</p><h2 id="enterprise-signal" tabindex="-1">Enterprise signal <a class="header-anchor" href="#enterprise-signal" aria-label="Permalink to &quot;Enterprise signal&quot;">​</a></h2><ul><li><strong>ServiceNow</strong> packages role-defined AI Specialists inside deterministic workflows, escalation and centralized governance.</li><li><strong>Workday</strong> treats Agents as workforce resources with ownership, cost, compliance and lifecycle.</li><li><strong>Salesforce</strong> packages business outcomes by function rather than selling abstract multi-agent capability.</li></ul><p>The market signal is clear: organizations buy completed work, not framework vocabulary.</p><h2 id="impact-on-tmpa" tabindex="-1">Impact on TMPA <a class="header-anchor" href="#impact-on-tmpa" aria-label="Permalink to &quot;Impact on TMPA&quot;">​</a></h2><p>TMPA should remain protocol-independent, define governance as executable lifecycle control, preserve SME-first positioning and evaluate evidence, escalation, recovery, human intervention and cost rather than only task success.</p><h2 id="impact-on-codeflowmu" tabindex="-1">Impact on CodeFlowMu <a class="header-anchor" href="#impact-on-codeflowmu" aria-label="Permalink to &quot;Impact on CodeFlowMu&quot;">​</a></h2><p>Recommended positioning:</p><blockquote><p><strong>CodeFlowMu is an SME-first Digital Employee Development and Runtime Platform.</strong></p></blockquote><p>Initial priorities are Position definition, Digital Employee Registry, workflow and operation-node contracts, runtime observability and recovery, TMPA/FCoP evidence lifecycle, and cost/evaluation records.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>The value of CodeFlowMu is not the number of Agents. It is the ability to turn probabilistic execution into accountable, recoverable and economically measurable organizational work.</p>`,19))])}const b=n(l,[["render",c]]);export{y as __pageData,b as default};
